/* Learner-facing Force Multiplier Fundamentals dashboard. Works offline within the existing simulator. */
(function(){'use strict';
const DATA=window.FMFundamentalsData; if(!DATA)return;
const ORDER=['scheduling','analysis','documentation','integrity','dbm'];
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STEP_LABELS=['Show Me','Help Me','Let Me Try','Challenge Me','Prove I Can Do It'];
const TEACH=()=>window.FMTeaching;
const icons={scheduling:'✈',analysis:'▥',documentation:'▤',integrity:'◈',dbm:'▣'};
function ensure(state){
 const f=state.fundamentals||(state.fundamentals={});
 if(!ORDER.includes(f.area))f.area='scheduling';
 if(!['overview','track','lesson'].includes(f.screen))f.screen='overview';
 if(!f.reviewed||typeof f.reviewed!=='object')f.reviewed={};
    // Task-specific questions were rewritten in 22.15. Keep all learner progress and
    // review evidence, but clear answers selected for the previous, unrelated quizzes.
    if(f.taskQuizEdition!=='22.15.0'){f.taskAnswers={};f.taskQuizEdition='22.15.0';}
 if(!f.quiz||typeof f.quiz!=='object')f.quiz={};
 if(!Number.isInteger(f.step)||f.step<0||f.step>4)f.step=0;
 if(!f.boardMode)f.boardMode='separate';
 if(!f.visual||typeof f.visual!=='object')f.visual={};
 if(!f.challengeVariant||typeof f.challengeVariant!=='object')f.challengeVariant={};
 if(!f.challengeAnswers||typeof f.challengeAnswers!=='object')f.challengeAnswers={};
 if(!f.proofCases||typeof f.proofCases!=='object')f.proofCases={};
 if(!f.proofDraft||typeof f.proofDraft!=='object')f.proofDraft={};
 if(!Array.isArray(f.proofRecords))f.proofRecords=[];
 if(!f.proofNotice||typeof f.proofNotice!=='object')f.proofNotice={};
 return f;
}
function all(){return ORDER.flatMap(k=>DATA[k].modules.map(m=>({...m,area:k})));}
function reviewedCount(f,key){return DATA[key].modules.filter(m=>f.reviewed[key+':'+m.id]).length;}
function percent(done,total){return Math.round(done/total*100);}
function progress(done,total){return `<div class="fund-progress" role="progressbar" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}"><span style="width:${percent(done,total)}%"></span></div>`;}
function breadcrumb(items){return `<nav class="fund-crumb" aria-label="Curriculum breadcrumb"><button data-fund-view="overview">Fundamentals</button>${items.map(x=>`<span aria-hidden="true">/</span>${x}`).join('')}</nav>`;}
function introBar(){return `<div class="fund-introbar"><span class="fund-mark">FM</span><span>FORCE MULTIPLIER <b>· REVENGE OF THE NONNER</b></span><span class="fund-no-timer">NO TIMER · OFFLINE</span></div>`;}
function overview(f){
 if(window.FMTaskMap) return window.FMTaskMap.render(f,false);
 const total=ORDER.reduce((n,k)=>n+reviewedCount(f,k),0),modules=all().length;
 return `<div class="fund-wrap" data-fund-screen="overview">${introBar()}
 <section class="fund-hero"><div class="fund-eyebrow">THE FIVE SPECIALTIES · YOUR LEARNING MAP</div><h1>Understand the job.<br><em>Practice the decision.</em></h1><p>Explore the fundamentals of Scheduling, Analysis, Documentation, Data Integrity and Database Management. Open a skill to learn what it means, see an example, test your judgment, then go directly to the block game or advanced trainer.</p><div class="fund-hero-actions"><button class="fund-btn primary" data-fund-area="scheduling">Start with Scheduling <span>→</span></button><button class="fund-btn subtle" data-route="academy:home">Open Block Academy <span>↗</span></button></div><div class="fund-overall"><div><strong>${total}<small> / ${modules}</small></strong><span>Lessons reviewed on this device</span></div><div><strong>100</strong><span>Observable skills mapped</span></div><div><strong>5</strong><span>Specialties</span></div></div></section>
 <section class="fund-section-header"><div><span class="fund-eyebrow">SELECT A SPECIALTY</span><h2>What will you learn?</h2><p>Each tile opens the fundamentals, the individual skills they contain, and the matching practice.</p></div><label class="fund-search-label">Search fundamentals<input id="fundSearch" autocomplete="off" placeholder="Try checkerboard, JML, denominator, audit…" aria-label="Search fundamentals and skills"></label></section>
 <div class="fund-overview-grid">${ORDER.map((key,i)=>{const a=DATA[key],done=reviewedCount(f,key);return `<button class="fund-specialty" style="--accent:${a.color}" data-fund-area="${key}" data-searchable="${E((a.name+' '+a.tag+' '+a.modules.map(m=>m.title+' '+m.outcome+' '+m.skills.map(s=>s.name).join(' ')).join(' ')).toLowerCase())}"><span class="fund-specialty-top"><span class="fund-specialty-icon">${icons[key]}</span><span class="fund-specialty-counter">${done}/${a.modules.length}</span></span><strong>${i+1}. ${E(a.name)}</strong><span class="fund-specialty-desc">${E(a.tag)}</span><span class="fund-specialty-topics">${a.modules.slice(0,3).map(m=>`<span>${E(m.title)}</span>`).join('')}</span>${progress(done,a.modules.length)}<span class="fund-open">Explore fundamentals <span aria-hidden="true">→</span></span></button>`}).join('')}</div>
 <div id="fundSearchEmpty" class="fund-search-empty" hidden>No matching specialties. Try a different skill or term.</div>
 <section class="fund-method"><div><span class="fund-eyebrow">LEARNING PATH</span><h2>From explanation to performance</h2><p>The dashboard teaches the fundamentals; Block Academy provides repetitions; advanced trainers require fuller decisions. Independent qualification still depends on authorized instructors, OJT and evidence of actual performance.</p></div><div class="fund-method-steps"><span>01 · Understand</span><span>02 · Observe</span><span>03 · Decide</span><span>04 · Practice</span><span>05 · Demonstrate</span></div></section><p class="fund-footnote">Curriculum basis: 11 November 2026 100 Skills Working Draft; 17 November FLUX workshop notes; Force Multiplier 22.11.0 training models. This is a proposed learning map, not an approved CFETP/STS or qualification determination.</p></div>`;
}
function track(f){const a=DATA[f.area],done=reviewedCount(f,f.area);
 return `<div class="fund-wrap" data-fund-screen="track" style="--track-accent:${a.color}">${introBar()}${breadcrumb([`<span>${E(a.name)}</span>`])}
 <section class="fund-track-hero"><div class="fund-eyebrow">SPECIALTY ${ORDER.indexOf(f.area)+1} OF 5 · 20 UNDERLYING SKILLS</div><h1>${E(a.name)}</h1><p>${E(a.tag)}</p><div class="fund-arc">${E(a.arc)}</div><div class="fund-track-meter"><span>${done} of ${a.modules.length} fundamentals reviewed</span>${progress(done,a.modules.length)}</div></section>
 <section class="fund-section-header"><div><span class="fund-eyebrow">FUNDAMENTALS</span><h2>Learn these in sequence</h2><p>Open any lesson to see the concept, an operational example, a decision check and practice.</p></div><button class="fund-btn subtle" data-route="flashcards:home">Study flashcards ↗</button></section>
 <div class="fund-lesson-grid">${a.modules.map((m,i)=>`<button class="fund-lesson-card" data-fund-lesson="${E(m.id)}"><span class="fund-lesson-num">${String(i+1).padStart(2,'0')} · ${E(m.kicker.toUpperCase())}</span><h3>${E(m.title)}</h3><p>${E(m.outcome)}</p><div class="fund-skill-tags">${m.ids.map(x=>`<span>${E(x)}</span>`).join('')}</div><div class="fund-lesson-foot"><span>${f.reviewed[f.area+':'+m.id]?'✓ Reviewed':'Explore lesson'}</span><span aria-hidden="true">→</span></div></button>`).join('')}</div>
 <details class="fund-all-skills"><summary><strong>See all 20 observable skills</strong><span>Original working-draft titles and required demonstrations</span></summary><div class="fund-task-list">${a.skills.map(s=>{const p=a.modules.find(m=>m.ids.includes(s.id));return `<button class="fund-task" data-fund-lesson="${E(p.id)}" data-fund-show-tasks="1"><span>${E(s.id)}</span><div><strong>${E(s.name)}</strong><p>${E(s.proof)}</p></div><span aria-hidden="true">↗</span></button>`}).join('')}</div></details>
 <div class="fund-track-actions"><button class="fund-btn primary" data-fund-lesson="${a.modules.find(m=>!f.reviewed[f.area+':'+m.id])?.id||a.modules[0].id}">Continue learning →</button><button class="fund-btn subtle" data-fund-view="overview">← All specialties</button></div></div>`;
}
function checkerboard(f){const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const condense=f.boardMode==='combined';const old=['PFR','PFR','CURE','PBG','PBG','CURE','READY'];const yes=['PFR','PFR','PBG','PBG','CURE','READY','READY'];const seq=condense?yes:old;return `<div class="fund-checker-demo"><div class="fund-checker-top"><div><b>Interactive checkerboard</b><p>Aircraft A05: two approved work packages, each requiring two workdays; one 24-hour cure can be shared when controlling instructions permit it.</p></div><div class="fund-toggle" role="group" aria-label="Choose maintenance sequence"><button data-fund-board="separate" class="${!condense?'active':''}">Separate</button><button data-fund-board="combined" class="${condense?'active':''}">Condensed</button></div></div><div class="fund-calendar-scroll"><div class="fund-calendar">${days.map((d,i)=>`<div class="fund-day ${i>=5?'weekend':''}"><span>${d}</span><strong class="fund-status ${seq[i]==='READY'?'ready':seq[i]==='CURE'?'cure':'work'}">${seq[i]}</strong></div>`).join('')}</div></div><div class="fund-demo-result"><span class="${condense?'positive':''}">${condense?'✓ One combined cure; available Saturday':'Two separate cures; available Sunday'}</span><p>${condense?'Because the assumed instructions allow consolidation, PFR and PBG are performed in order and the single final cure follows both. A Saturday return is a scenario assumption—not an automatic policy rule.':'Separate cure intervals use another day. This plan may still be required if technical instructions prohibit combining the work.'}</p></div><div class="fund-teaching-note">Scheduling fundamentals taught here: identify due work, find a compatible downtime window, confirm work order and prerequisites, protect required cure time, document the decision, and recompute aircraft availability. Never combine jobs contrary to controlling technical data.</div></div>`;}
function extraVisual(m,f){if(f.area==='scheduling'&&m.id==='checkerboard')return checkerboard(f);
 if(f.area==='scheduling'&&m.id==='phase')return `<div class="fund-phase-demo"><div><strong>Phase Flow</strong><span>Hours remaining until the recurring inspection</span></div>${[['A08',0],['A01',30],['A02',48],['A03',66],['A04',90],['A05',105],['A06',132],['A07',150]].map(([id,h])=>`<div class="fund-phase-row"><strong>${id}</strong><span><i style="width:${Math.max(2,h/150*100)}%"></i></span><b>${h} h</b></div>`).join('')}<p>Shorter bar = closer to Phase. Each flying decision consumes hours and changes the forecast.</p></div>`;
 if(f.area==='analysis'&&m.id==='rates')return `<div class="fund-formula-demo"><strong>8-hour fix rate</strong><div><span>2 breaks fixed within 8 hours</span><b>÷</b><span>10 qualifying breaks</span><b>× 100 = 20%</b></div><p>Do not substitute sorties for the denominator of this metric.</p></div>`;
 if(f.area==='documentation'&&['forecast','jml'].includes(m.id))return `<div class="fund-jml-demo"><strong>Requirement → JML → Work → Evidence</strong><div><span>Current technical requirement</span><span>Applicable asset & due point</span><span>Scheduled work</span><span>Verified accomplishment</span></div><p>The JML and status report must trace back to the controlling requirement and matching accomplishment evidence.</p></div>`;
 return '';
}
const CHALLENGES={
 scheduling:[{question:'A required spare becomes NMC after the schedule is coordinated. What should the scheduler do?',answers:['Keep the lineup; the calendar is already approved','Recheck capability and constraints, identify another eligible spare or report a shortfall, and coordinate the revision','Use the NMC aircraft as a spare without noting the restriction'],answer:1,why:'The schedule must remain executable after status changes.'},{question:'A proposed consolidation removes a required intermediate cure. What action is justified?',answers:['Reject that sequence until controlling instructions establish it is permitted','Combine it to maximize flying time','Delete the cure entry from the checkerboard'],answer:0,why:'Maintenance optimization never overrides technical instructions.'}],
 analysis:[{question:'Two reports disagree on a maintenance rate because their denominators differ. What is your first move?',answers:['Average the two reported percentages','Use the higher number to avoid an alarm','Check event population, exclusions, source periods and authorized metric definition'],answer:2,why:'Reconcile what counts before using a rate to advise a commander.'},{question:'A strong correlation appears after an operational change. What conclusion is supported?',answers:['The change definitely caused the result','It warrants investigation with alternative explanations and data-quality checks','The metric proves the fleet is safe'],answer:1,why:'Correlation is not proof of causation.'}],
 documentation:[{question:'A record says work is complete, but the accomplishment evidence refers to a different aircraft. What now?',answers:['Keep the status as complete','Correct the source paperwork without approval','Hold or correct the status using authoritative source evidence and authorized procedures'],answer:2,why:'Status must be supported by applicable evidence for the correct asset.'},{question:'A planned modification is due but its controlling applicability instruction is unclear. What now?',answers:['Verify applicability and authority before scheduling or closing the requirement','Assume all aircraft require it','Copy the previous aircraft record'],answer:0,why:'No work or completion should be invented from ambiguity.'}],
 integrity:[{question:'A system value differs from an approved document, but another current source conflicts with it. What now?',answers:['Choose the higher value','Preserve the discrepancy and investigate source authority before changing data','Delete both records'],answer:1,why:'A mismatch is a reason to investigate—not automatic correction authority.'},{question:'After an authorized correction, an automated report still shows the old value. What must happen?',answers:['Close the case when the source is corrected','Overwrite the report without an audit trail','Verify dependent data flow and report propagation, retaining the change evidence'],answer:2,why:'A correction is incomplete if downstream decisions still use bad data.'}],
 dbm:[{question:'A user cannot see a report. What action is safest before granting privileges?',answers:['Identify the failing layer, role scope and report filters, then verify authorization','Give administrator access to rule out permissions','Delete the user account'],answer:0,why:'A visibility issue does not authorize broad permissions.'},{question:'An interface rejects one record while several others imported correctly. What is safest?',answers:['Replay the entire feed to ensure completeness','Investigate mapping and transaction identity, then reprocess only the authorized rejected record','Ignore the problem because most records succeeded'],answer:1,why:'Uncontrolled replay can create duplicates or lose history.'}]
};
const UNEXPECTED={
 scheduling:['A required aircraft becomes NMC immediately before the flying meeting.','The only Phase dock becomes unavailable for a day.','An urgent mission increases flying demand while the available spare is restricted.'],
 analysis:['A supervisor provides a revised denominator and asks whether your conclusion still holds.','Two periods use different aircraft populations and one data extract is missing.','A commander asks whether correlation means a proposed fix caused improvement.'],
 documentation:['The accomplishment signature belongs to a different aircraft.','A controlled requirement has changed effective date after the plan was drafted.','The JML shows completion but the work package contains only partial evidence.'],
 integrity:['Two approved-looking records conflict and neither source is clearly controlling.','A correction changes the source record but the receiving report remains stale.','A repeated event has the same description but a different valid event identifier.'],
 dbm:['A user loses access immediately after a role change.','An interface rejects one transaction after the other records succeeded.','A restored backup contains older access permissions that may be inappropriate.']
};
function challengeFor(f,m,key){const v=f.challengeVariant[key]||0;return v===0?{question:m.question,answers:m.answers,answer:m.answer,why:m.answerWhy}:CHALLENGES[f.area][v-1];}
function proofCard(f,m,key){const v=f.proofCases[key]||0,d=f.proofDraft[key]||{},msg=f.proofNotice[key]||'',saved=f.proofRecords.filter(x=>x.key===key).length;return `<section class="fund-prove-card"><span class="fund-slide-eyebrow">FRESH TASK · INDEPENDENT WORK RECORD</span><h3>Case ${v+1} — demonstrate your decision</h3><p>${E(m.scenario)} <b>New condition:</b> ${E(UNEXPECTED[f.area][v])}</p><p>Work in the real exercise and then record your decision. Avoid hints and model answers during the independent attempt. These responses are saved for instructor review; they are not automatically graded.</p><div class="fund-prove-inputs">${[['decision','Decision and changed plan'],['evidence','Source, evidence and applicable constraints'],['risk','Residual risk / unresolved items'],['brief','What you would tell the supervisor']].map(([field,label])=>`<label>${label}<textarea data-fund-proof="${field}" maxlength="8000" placeholder="State the specific work product, rationale and next step...">${E(d[field]||'')}</textarea></label>`).join('')}</div><div class="fund-practice-buttons"><button type="button" data-fund-proof-save="1">Save attempt for instructor review</button><button type="button" data-fund-proof-next="1">New case variation ↻</button></div>${msg?`<p class="fund-proof-status" role="status">${E(msg)}</p>`:''}<small>${saved} saved attempt(s) for this fundamental on this device. Only an authorized trainer can evaluate real-world qualification.</small></section>`;}
function lesson(f){const a=DATA[f.area],m=a.modules.find(x=>x.id===f.lesson)||a.modules[0],i=a.modules.indexOf(m),key=f.area+':'+m.id,step=f.step;
 const visual=f.visual[key]||'good',teach=TEACH();
 const gallery=()=>teach?teach.gallery(f.area,m,visual):'';
 const worked=m.steps.map((s,k)=>`<div class="fund-method-row"><span>${String(k+1).padStart(2,'0')}</span><p>${E(s)}</p></div>`).join('');
 let content='';
 if(step===0)content=`<span class="fund-slide-eyebrow">SHOW ME · WHAT GOOD LOOKS LIKE</span><h2>${E(m.title)}</h2><p class="fund-lead">${E(m.outcome)}</p><div class="fund-why"><strong>Why it matters</strong><p>${E(m.why)}</p></div><h3>At the end, you should be able to…</h3><div class="fund-outcomes">${m.skills.map(s=>`<div><strong>${E(s.id)} · ${E(s.name)}</strong><p>${E(s.proof)}</p></div>`).join('')}</div>${gallery()}`;
 if(step===1)content=`<span class="fund-slide-eyebrow">HELP ME · EXPLAIN EACH MOVE</span><h2>Learn the process</h2><p class="fund-lead">Move through the task deliberately. Do not skip a constraint just to finish faster.</p><div class="fund-method-list">${worked}</div><div class="fund-why"><strong>The six-part performance habit</strong><p>Discover → Evaluate → Decide → Act → Communicate → Defend. Keep your inputs, assumptions, authority, and rationale visible.</p></div>`;
 if(step===2)content=`<span class="fund-slide-eyebrow">LET ME TRY · EXPLORE THREE CASES</span><h2>Watch it in context</h2><p class="fund-lead">${E(m.scenario)}</p>${gallery()}${extraVisual(m,f)}<div class="fund-why"><strong>What to notice</strong><p>${E(m.why)}</p></div>`;
 if(step===3){const v=f.challengeVariant[key]||0,x=challengeFor(f,m,key),choice=f.challengeAnswers[key]?.[v]??(v===0?f.quiz[key]:undefined),passed=f.challengeAnswers[key]||{};
  content=`<span class="fund-slide-eyebrow">CHALLENGE ME · THREE DECISIONS WITH FADING HELP</span><h2>${E(x.question)}</h2><p class="fund-lead">Case ${v+1} of 3 · Choose the best answer using the controlling facts, then review your reasoning.</p><div class="fund-answer-grid">${x.answers.map((a,k)=>`<button class="fund-answer ${choice===k?'selected':''} ${choice===k?(k===x.answer?'correct':'incorrect'):''}" data-fund-quiz="${k}"><span>${String.fromCharCode(65+k)}</span>${E(a)}</button>`).join('')}</div>${choice!==undefined?`<div class="fund-response ${choice===x.answer?'good':'bad'}"><strong>${choice===x.answer?'Correct. The decision is supported.':'Not yet. Revisit the constraints.'}</strong><p>${E(x.why)}</p></div>`:''}<div class="fund-practice-checkpoint"><h3>Practice across changing conditions</h3><p>${Object.entries(passed).filter(([j,a])=>a===challengeFor({...f,challengeVariant:{[key]:Number(j)}},m,key).answer).length} of 3 challenge decisions correct in this lesson.</p><button type="button" data-fund-case-next="1">${v<2?'Next unfamiliar challenge →':'Try these three again ↻'}</button></div>`;
 }
 if(step===4)content=`<span class="fund-slide-eyebrow">PROVE I CAN DO IT · REVIEWABLE EVIDENCE</span><h2>Practice the decision</h2><p class="fund-lead">Repeat the fundamentals in the existing game, then use the deeper trainer to make decisions in a larger case. Save an independent work record below for instructor review.</p><div class="fund-practice-buttons"><button class="fund-btn primary" data-academy-mission="${m.mission}">▶ ${E(m.mission<=3?'Play scheduling blocks':'Play specialty blocks')}</button><button class="fund-btn secondary" data-fund-advanced="${E(m.advanced)}">Open related advanced trainer ↗</button><button class="fund-btn subtle" data-route="flashcards:home">Study flashcards</button></div><div class="fund-why"><strong>What does practice cover?</strong><p>Block Academy currently has seven game missions and 90 rounds per mission. This lesson links to its nearest relevant exercise; some advanced topics are covered more directly in the trainer. Completing a game is not evidence of occupational qualification.</p></div>${proofCard(f,m,key)}<details class="fund-evidence"><summary>What would independent performance look like?</summary><ul>${m.skills.map(s=>`<li><b>${E(s.id)}</b>: ${E(s.proof)}</li>`).join('')}</ul><p>In a fresh case, require an actual work product and an explanation of the decision. Critical compliance or safety errors cannot be offset with a high score.</p></details>`;
 return `<div class="fund-wrap" data-fund-screen="lesson" style="--track-accent:${a.color}">${introBar()}${breadcrumb([`<button data-fund-area="${E(f.area)}">${E(a.name)}</button>`,`<span>${E(m.title)}</span>`])}
 <div class="fund-lesson-shell"><aside class="fund-lesson-rail"><span class="fund-eyebrow">${E(a.name.toUpperCase())} · FUNDAMENTAL ${i+1}/${a.modules.length}</span><h2>${E(m.title)}</h2><p>${E(m.outcome)}</p><div class="fund-rail-list">${STEP_LABELS.map((s,k)=>`<button class="${k===step?'current':''}" data-fund-step="${k}"><span>${k===step?'●':(k<step?'✓':String(k+1))}</span>${E(s)}</button>`).join('')}</div><div class="fund-rail-progress">${progress(step+1,5)}</div><button class="fund-rail-return" data-fund-area="${E(f.area)}">← All ${E(a.name)} fundamentals</button></aside>
 <section class="fund-lesson-content"><div class="fund-lesson-topline"><span>${E(m.kicker.toUpperCase())}</span><span>STAGE ${step+1} / 5</span></div><div class="fund-step-content">${content}</div><div class="fund-step-footer"><button class="fund-btn subtle" data-fund-step="${Math.max(0,step-1)}" ${step===0?'disabled':''}>← Previous</button><button class="fund-btn primary" data-fund-next="1">${step===4?'Continue to next skill':step===3&&f.quiz[key]!==m.answer?'Skip to practice':'Next →'}</button></div><div class="fund-lesson-lower"><span>${f.reviewed[key]?'✓ Quick decision answered correctly · lesson reviewed':'Learning note: no official qualification awarded.'}</span><button data-fund-view="track">View specialty map ↗</button></div></section></div>
 <div class="fund-related"><div><span class="fund-eyebrow">UNDERLYING TASKS</span><h3>${m.skills.length} original skill demonstrations</h3></div>${m.skills.map(s=>`<details><summary><strong>${E(s.id)} · ${E(s.name)}</strong></summary><p>${E(s.proof)}</p></details>`).join('')}</div><div class="fund-next-strip"><button class="fund-btn subtle" data-fund-view="track">← ${E(a.name)} overview</button>${i<a.modules.length-1?`<button class="fund-btn secondary" data-fund-lesson="${E(a.modules[i+1].id)}">Next fundamental: ${E(a.modules[i+1].title)} →</button>`:`<button class="fund-btn secondary" data-fund-view="overview">All five specialties →</button>`}</div></div>`;
}
function render(state){const f=ensure(state);return f.screen==='track'?track(f):f.screen==='lesson'?lesson(f):overview(f)}
function handleClick(dataset,state,ui){if(window.FMTaskMap&&window.FMTaskMap.handleClick(dataset,state,ui))return true;const f=ensure(state);
 if(dataset.fundView){f.screen=dataset.fundView;f.step=0;ui.save();ui.setRoute('fundamentals','home');return true;}
 if(dataset.fundArea){f.area=dataset.fundArea;f.screen='track';f.step=0;ui.save();ui.setRoute('fundamentals','home');return true;}
 if(dataset.fundLesson){const a=DATA[f.area],m=a.modules.find(m=>m.id===dataset.fundLesson);if(!m)return true;f.lesson=m.id;f.screen='lesson';f.step=dataset.fundShowTasks?4:0;ui.save();ui.setRoute('fundamentals','home');return true;}
 if(dataset.teachCase!==undefined){const key=f.area+':'+f.lesson;f.visual[key]=dataset.teachCase;ui.save();ui.render();return true;}
 if(dataset.fundCaseNext!==undefined){const key=f.area+':'+f.lesson;f.challengeVariant[key]=((f.challengeVariant[key]||0)+1)%3;ui.save();ui.render();return true;}
 if(dataset.fundProofNext!==undefined){const key=f.area+':'+f.lesson;f.proofCases[key]=((f.proofCases[key]||0)+1)%3;f.proofNotice[key]='';f.proofDraft[key]={};ui.save();ui.render();return true;}
 if(dataset.fundProofSave!==undefined){const key=f.area+':'+f.lesson,d=f.proofDraft[key]||{};if(!['decision','evidence','risk','brief'].every(x=>(d[x]||'').trim().length>=18)){f.proofNotice[key]='Complete all four work-product fields with specific explanations (at least 18 characters each).';}else{f.proofRecords.push({key,at:new Date().toISOString(),variation:f.proofCases[key]||0,mode:'ungraded submission for instructor review',...d});f.proofRecords=f.proofRecords.slice(-250);f.proofNotice[key]='Attempt saved locally. An instructor still needs to review the work product and critical errors.';}ui.save();ui.render();return true;}
 if(dataset.fundStep!==undefined){f.step=Math.max(0,Math.min(4,Number(dataset.fundStep)));ui.save();ui.render();return true;}
 if(dataset.fundNext){const a=DATA[f.area],i=a.modules.findIndex(m=>m.id===f.lesson);if(f.step<4){f.step++;ui.save();ui.render()}else if(i<a.modules.length-1){f.lesson=a.modules[i+1].id;f.step=0;ui.save();ui.render();window.scrollTo(0,0)}else{f.screen='track';f.step=0;ui.save();ui.render();window.scrollTo(0,0)}return true;}
 if(dataset.fundQuiz!==undefined){const m=DATA[f.area].modules.find(m=>m.id===f.lesson);const key=f.area+':'+m.id,v=f.challengeVariant[key]||0,x=challengeFor(f,m,key);const ans=Number(dataset.fundQuiz);f.challengeAnswers[key]=f.challengeAnswers[key]||{};f.challengeAnswers[key][v]=ans;if(v===0){f.quiz[key]=ans;if(ans===m.answer)f.reviewed[key]=true;}ui.save();ui.render();return true;}
 if(dataset.fundBoard){f.boardMode=dataset.fundBoard;ui.save();ui.render();return true;}
 if(dataset.fundAdvanced){const [mod,screen='home']=dataset.fundAdvanced.split(':');ui.setRoute(mod,screen);return true;}
 return false;
}
function attach(root){root.addEventListener('input',ev=>{if(ev.target.id!=='fundSearch')return;const q=ev.target.value.trim().toLowerCase();let visible=0;root.querySelectorAll('[data-searchable]').forEach(el=>{const ok=el.dataset.searchable.includes(q);el.hidden=!ok;if(ok)visible++});const e=root.querySelector('#fundSearchEmpty');if(e)e.hidden=visible>0;});}
window.FMFundamentals={render,handleClick,attach,DATA,all,ensure};
})();
